#include <stdint.h>
#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

/* Read exactly one text line, with or without a final newline. */
static int read_value(long *out)
{
    char line[64];
    size_t used = 0;
    int ch;
    int invalid = 0;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || ch > CHAR_MAX || used == sizeof line - 1) {
            invalid = 1;
        } else {
            line[used++] = (char)ch;
        }
    }
    if (invalid || ferror(stdin) || used == 0) {
        return 0;
    }
    line[used] = '\0';

    char *end;
    errno = 0;
    long value = strtol(line, &end, 10);
    if (end == line || errno == ERANGE) {
        return 0;
    }
    while (isspace((unsigned char)*end)) {
        ++end;
    }
    if (*end != '\0') {
        return 0;
    }
    *out = value;
    return 1;
}

static int copy_at(const int values[], size_t count, long input, int *out)
{
    if (input < 0) {
        return 0;
    }
    uintmax_t index = (uintmax_t)input;
    if (index >= count) {
        return 0;
    }
    *out = values[(size_t)index];
    return 1;
}

int main(void)
{
    long input;
    if (!read_value(&input)) {
        puts("invalid");
        return 0;
    }

    int saved;
    const int values[] = {8, 13};
    size_t count = sizeof values / sizeof values[0];
    if (!copy_at(values, count, input, &saved)) {
        puts("invalid");
        return 0;
    }
    printf("%d\n", saved);
    return 0;
}

